import json
import sys

ALLOWED = {'Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias', 'Phony'}


def solve(lines):
    sys.setrecursionlimit(10000)
    blocks = []
    cur = None
    for raw in lines:
        s = raw.strip()
        if not s or s.startswith('#'):
            continue
        if s.startswith('[') and s.endswith(']'):
            continue
        tokens = s.split()
        if tokens[0] == 'TARGET':
            if len(tokens) != 2:
                return 'PARSE_ERROR'
            cur = {'kind': 'T', 'name': tokens[1], 'id': None, 'dirs': []}
            blocks.append(cur)
        elif tokens[0] == 'OVERRIDE':
            if len(tokens) != 3:
                return 'PARSE_ERROR'
            cur = {'kind': 'O', 'name': tokens[1], 'id': tokens[2], 'dirs': []}
            blocks.append(cur)
        else:
            if cur is None or s.count('=') != 1:
                return 'PARSE_ERROR'
            k, v = s.split('=', 1)
            k = k.strip()
            v = v.strip()
            if k not in ALLOWED:
                return 'PARSE_ERROR'
            if k == 'Phony':
                if v not in ('yes', 'no'):
                    return 'PARSE_ERROR'
                cur['dirs'].append(('Phony', v))
            else:
                cur['dirs'].append((k, v.split()))

    # Union-find for aliases
    parent = {}

    def find(x):
        if x not in parent:
            parent[x] = x
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    universe = set()
    for b in blocks:
        universe.add(b['name'])
        find(b['name'])
        for k, vals in b['dirs']:
            if k == 'Phony':
                continue
            for v in vals:
                universe.add(v)
                find(v)
            if k == 'Alias':
                for v in vals:
                    union(b['name'], v)

    comp_min = {}
    for x in list(parent.keys()):
        r = find(x)
        if r not in comp_min or x < comp_min[r]:
            comp_min[r] = x

    def canon(x):
        return comp_min[find(x)]

    ordered = [b for b in blocks if b['kind'] == 'T']
    ordered += sorted([b for b in blocks if b['kind'] == 'O'], key=lambda b: b['id'])

    # Node discovery order
    node_list = []
    node_set = set()

    def add_node(n):
        if n not in node_set:
            node_set.add(n)
            node_list.append(n)

    edges = set()
    for b in ordered:
        U = canon(b['name'])
        add_node(U)
        for k, vals in b['dirs']:
            if k == 'Phony':
                continue
            for v in vals:
                add_node(canon(v))
            if k == 'Alias':
                continue
            for v in vals:
                c = canon(v)
                if k in ('Depends', 'After'):
                    edges.add((c, U))
                else:
                    edges.add((U, c))
    for u in sorted(universe):
        add_node(canon(u))

    n = len(node_list)
    index_of = {name: i for i, name in enumerate(node_list)}
    adj = [[] for _ in range(n)]
    self_loop = [False] * n
    for a, bb in edges:
        ia, ib = index_of[a], index_of[bb]
        adj[ia].append(ib)
        if ia == ib:
            self_loop[ia] = True

    # Tarjan SCC
    counter = [0]
    idx = {}
    low = {}
    stack = []
    onstack = set()
    comps = []

    def strong(v):
        idx[v] = low[v] = counter[0]
        counter[0] += 1
        stack.append(v)
        onstack.add(v)
        for w in adj[v]:
            if w not in idx:
                strong(w)
                low[v] = min(low[v], low[w])
            elif w in onstack:
                low[v] = min(low[v], idx[w])
        if low[v] == idx[v]:
            comp = []
            while True:
                w = stack.pop()
                onstack.discard(w)
                comp.append(w)
                if w == v:
                    break
            comps.append(comp)

    for v in range(n):
        if v not in idx:
            strong(v)

    nc = len(comps)
    comp_of = [0] * n
    members = []
    for cid, comp in enumerate(comps):
        for v in comp:
            comp_of[v] = cid
        members.append(sorted(node_list[v] for v in comp))
    rep = [members[c][0] for c in range(nc)]
    first_idx = [min(index_of[m] for m in members[c]) for c in range(nc)]

    cycles = []
    for cid in range(nc):
        if len(members[cid]) >= 2 or (len(members[cid]) == 1 and self_loop[index_of[members[cid][0]]]):
            cycles.append(members[cid])
    cycles.sort()

    csucc = [set() for _ in range(nc)]
    indeg = [0] * nc
    for a, bb in edges:
        ca, cb = comp_of[index_of[a]], comp_of[index_of[bb]]
        if ca != cb and cb not in csucc[ca]:
            csucc[ca].add(cb)
            indeg[cb] += 1

    queue = [c for c in sorted(range(nc), key=lambda c: first_idx[c]) if indeg[c] == 0]
    order = []
    while queue:
        c = queue.pop(0)
        order.extend(members[c])
        for d in csucc[c]:
            indeg[d] -= 1
            if indeg[d] == 0:
                queue.append(d)
        queue.sort(key=lambda x: rep[x])

    return json.dumps({'order': order, 'cycles': cycles}, separators=(',', ':'))
